INSERT INTO `games` VALUES
('1', '1', 'Fast Parity', 'fast-parity', 'fast_parity', '/images/games/fast_parity.png', 'bi-lightning', '10.00', '50000.00', '2.00', '96.00', '1', 'Predict Red, Green, Violet or Number 0-9. Period rotates every 30 seconds.', 'Choose your bet color or number before countdown ends.', '{\"timer_seconds\": 30}', '2026-07-30 09:42:45', '2026-07-30 09:42:45'),
('2', '1', 'Mines', 'mines', 'mines', '/images/games/mines.png', 'bi-pin-angle', '10.00', '100000.00', '1.20', '97.00', '1', 'Uncover tiles on a 5x5 grid without hitting bombs to increase your payout multiplier.', 'Cash out at any time to claim your accumulated winnings.', '{\"grid_size\": 25, \"default_mines\": 3}', '2026-07-30 09:42:45', '2026-07-30 10:51:20'),
('3', '2', 'Crash', 'crash', 'crash', '/images/games/crash.png', 'bi-graph-up-arrow', '10.00', '100000.00', '1.01', '95.00', '1', 'Watch the rocket multiplier climb e.g. 1.5x, 3x, 50x. Cash out before it crashes!', 'Set auto-cashout or click Cash Out manually during flight.', '{\"speed\": 1.1}', '2026-07-30 09:42:45', '2026-07-30 11:15:38'),
('4', '2', 'JetX Flight', 'jet', 'jet', '/images/games/jet.png', 'bi-rocket', '50.00', '100000.00', '1.01', '96.00', '1', 'High-altitude Jet rocket game with dynamic multiplier curve.', 'Eject passengers before atmospheric explosion.', '{\"speed\": 1.2}', '2026-07-30 09:42:45', '2026-07-30 09:42:45'),
('5', '3', 'Parity (3-Min)', 'parity', 'parity', '/images/games/parity.png', 'bi-clock-history', '10.00', '50000.00', '2.00', '96.50', '1', 'Classic 3-minute period color prediction room with higher entry limits.', 'Place your bets on Green, Violet, Red, or Number.', '{\"timer_seconds\": 180}', '2026-07-30 09:42:45', '2026-07-30 09:42:45'),
('6', '4', 'Spin Wheel', 'spin-wheel', 'spin_wheel', '/images/games/spin_wheel.png', 'bi-arrow-repeat', '10.00', '20000.00', '10.00', '94.00', '1', 'Spin the wheel to hit lucky multipliers e.g. 2x, 5x, 10x, 50x.', 'Select stake amount and press Spin.', '{\"sectors\": [2, 3, 5, 10, 50]}', '2026-07-30 09:42:45', '2026-07-30 09:42:45'),
('7', '4', 'Dice Roll', 'dice', 'dice', '/images/games/dice.png', 'bi-dice-5', '10.00', '50000.00', '1.98', '98.00', '1', 'Roll over or roll under target number.', 'Adjust slider target to configure payout odds.', '{\"max_target\": 95, \"min_target\": 5}', '2026-07-30 09:42:45', '2026-07-30 11:23:40'),
('8', '4', 'Andar Bahar', 'andar-bahar', 'andar_bahar', '/images/games/andar_bahar.png', 'bi-suit-spade-fill', '10.00', '50000.00', '2.00', '96.00', '1', 'Traditional Indian Card Game. Predict whether the matching card rank lands on Andar, Bahar, or Tie.', 'Choose Andar (2x), Bahar (2x), or Tie (9x) before the 45s countdown ends.', '{\"round_seconds\":60,\"betting_seconds\":45}', '2026-08-01 11:44:20', '2026-08-01 11:44:20');
